import { CHAT_COLOURS, Environment, ICurrencySettings, ITimeLocale, PartialWithPickRequired } from '@game-studio/utilities';
import { IBaseParentEvents, UnionizeArray } from '.';

// #region METHODS
export interface IChatChildEvents {
    disconnect(): void;
    setup(payload: IBootstrapConfigPayload): void;
    showLobbyButton(payload: IShowLobbyButtonPayload): void;
    sendMessage(payload: ISendMessagePayload): void;
    setChatColour(payload: IChatColourPayload): void;
    setChatSize(payload: IChatFontSizePayload): void;
    setChatStyle(payload: IChatStylePayload): void;
    setDemoMode(payload: IShowDemoModePayload): void;
    setWarmBackground(payload: IWarmBackgroundPayload): void;
    isActionMenuChatShowing(payload: IActionMenuChatPayload): void;
    connectToRoom(payload: IRoomConfigPayload): void;
    onLoseFocus(): void;
    setChatClosedOverlay(payload: IShowChatClosedOverlayPayload): void;
    onPromoRequest(payload: IPromoRequestPayload): void;
}

export interface IChatParentEvents extends IBaseParentEvents {
    onInit(): void;
    onKeyboardOpened(payload: { isOpen: boolean }): void;
    goToLobby(): void;
    setChatColour(payload: IChatColourPayload): void;
    toggleFullScreen(payload: IChatFullScreenPayload): void;
    onMessageReceived(payload: IMessageReceivedPayload): void;
    /** @deprecated Use onLinkClicked instead */
    onLiveChatClicked(): void;
    onLinkClicked(payload?: IChatLinksPayload): void;
    onArcadeWinner(payload: IArcadeWinnerPayload): void;
    onChatNotification(): void;
    provideAllChatColours(payload: IProvideChatColoursPayload[]): void;
}
// #endregion

// #region PAYLOADS
export type IBootstrapConfigPayload = IBingoBootstrapConfig | IGlobalBootstrapConfig;

export interface SVGIconOptions {
    useSymbolAsMask: boolean;
    foregroundOpacity: number;
    backgroundOpacity: number;
}

export interface UserListIconOptions extends SVGIconOptions {
    isEligibleForPromo?: boolean;
    excalamationHexColour?: string;
}

export interface IChatFontSizePayload {
    size: UnionizeArray<typeof CHAT_FONT_SIZES>;
}

export interface IChatStylePayload {
    backgroundColor: string;
    color: string;
    options?: SVGIconOptions;
}

export interface IRoomConfigPayload {
    roomId: number;
    roomName?: string;
    manualUserList?: boolean;
    sessionToken?: string;
    authToken?: string;
}

export interface IArcadeWinnerPayload {
    username: string;
    prize: number;
    game: string;
    skin: string;
}

export interface IMessageReceivedPayload {
    username: string;
    content: string;
    messageId: number;
    color?: string;
    type: ChatMessageType;
}

export interface IChatLinksPayload {
    url: string;
}

export interface IShowLobbyButtonPayload {
    show: boolean;
}

export interface ISendMessagePayload {
    message: string;
}

export interface IChatColourPayload {
    colour: string;
}

export interface IShowDemoModePayload {
    show: boolean;
}

export interface IChatFullScreenPayload {
    fullScreen: boolean;
}

export interface IWarmBackgroundPayload {
    warm: boolean;
}

export interface IActionMenuChatPayload {
    showing: boolean;
}

export interface IProvideChatColoursPayload {
    id: number,
    name: string,
    hexColour: string
}

export interface IShowChatClosedOverlayPayload {
    show: boolean;
}

export interface IPromoRequestPayload {
    promotype: string;
    start: string;
    end: string;
    prizesum: number;
}
// #endregion

// #region TYPES
// TODO: Worth moving these types into utilities? Since chat project will more than likely use them too
const USER_TYPES = ['player', 'host', 'chatbot'] as const;
const CHAT_MESSAGE_TYPES = ['isHost', 'isChatBot', 'system', 'player', 'prize', 'welcome'] as const;
const COUNTRIES = ['uk', 'spain', 'denmark', 'sweden', 'netherlands'] as const;
export const CHAT_FONT_SIZES = ['small', 'medium', 'large'] as const;

export type UserType = UnionizeArray<typeof USER_TYPES>;
export type Country = UnionizeArray<typeof COUNTRIES>;
export type ChatMessageType = UnionizeArray<typeof CHAT_MESSAGE_TYPES>;
export type IChatFontSize = UnionizeArray<typeof CHAT_FONT_SIZES>;
export type IChatColourConfig = typeof CHAT_COLOURS;
export type IChatColour = typeof CHAT_COLOURS[number];

export interface IChatServerOptions {
    welcomeMessageFactory: (roomName?: string) => string;
    webSocketUrl: string;
}

export interface IButtonStyle {
    backgroundColour: string;
    textColour: string;
}

export type IIncomingChatTranslations = PartialWithPickRequired<IChatTranslations, 'WELCOME'>;

interface IBaseBootstrapConfig {
    userId: number | string;
    crosscheck: number;
    operatorId?: string;
    gameName: string;
    friendlyGameNameMap: Record<string, string>;
    environment: Environment;
    chatSize: IChatFontSize;
    chatColour: string;
    warmBackground: boolean;
    chatStyle: IChatStyle;
    isInDemoMode: boolean;
    reconnectButtonStyle: IButtonStyle;
    currencySettings: ICurrencySettings
    userListEnabled: boolean;
    enableEmojis?: boolean;
    locale?: IBootstrapConfigLocale;
    /** When true, room configs are fetched from the B2B config portal instead of the legacy API. Defaults to false */
    useConfigPortal?: boolean;
}

interface ILocalTranslationsBootstrapConfig extends IBaseBootstrapConfig {
    translations: IChatTranslations;
    useRemoteTranslations?: false;
}

interface IRemoteTranslationsBootstrapConfig extends IBaseBootstrapConfig {
    translations: IIncomingChatTranslations;
    useRemoteTranslations: true;
    remoteTranslationsVersion?: number;
}

interface IBaseBootstrapConfig {
    userId: number | string;
    crosscheck: number;
    operatorId?: string;
    gameName: string;
    environment: Environment;
    chatSize: IChatFontSize;
    chatColour: string;
    warmBackground: boolean;
    chatStyle: IChatStyle;
    isInDemoMode: boolean;
    reconnectButtonStyle: IButtonStyle;
    currencySettings: ICurrencySettings
    userListEnabled: boolean;
    enableEmojis?: boolean;
    locale?: IBootstrapConfigLocale;
    translations: IIncomingChatTranslations;
    useRemoteTranslations?: boolean;
    remoteTranslationsVersion?: number;
    /** When true, room configs are fetched from the B2B config portal instead of the legacy API. Defaults to false */
    useConfigPortal?: boolean;
}
interface IBingoConfig {
    platform: 'bingo';
    websocketUrl: string;
    showHomeButton: boolean;
}
interface IGlobalConfig {
    platform: 'arcade';
    sessionToken?: string;
    authToken?: string;
}

export type IBingoBootstrapConfig = (ILocalTranslationsBootstrapConfig & IBingoConfig) | (IRemoteTranslationsBootstrapConfig & IBingoConfig);
export type IGlobalBootstrapConfig = (ILocalTranslationsBootstrapConfig & IGlobalConfig) | (IRemoteTranslationsBootstrapConfig & IGlobalConfig);

export type IBootstrapConfigLocale = 'uk' | 'it' | 'es' | 'dk' | 'se';
export type IBootstrapConfig = IBingoBootstrapConfig | IGlobalBootstrapConfig;

export interface IChatStyle {
    backgroundColor: string;
    color: string;
    options?: SVGIconOptions;
}

export interface IChatTranslations {
    WELCOME: {
        GAME_TEMPLATE_WELCOME: string;
        ROOM_TEMPLATE_WELCOME: string;
    }
    USER_LIST: {
        PLACEHOLDER: string;
    }
    MESSAGE_INPUT: {
        PLACEHOLDER: string;
    }
    BANNED: {
        TITLE: string;
        BODY_1: string;
        BODY_1_LINK: string;
        BODY_2: string;
    }
    SINNED: {
        TITLE: string;
        BODY_1: string;
        BODY_2: string;
        BODY_3: string;
    }
    TIME_FORMAT_LOCALE: ITimeLocale,
    DISCONNECTED: {
        BODY_1: string;
        BODY_2: string;
        RECONNECT_BUTTON: string;
    }
    DEMO_MODE: {
        TITLE: string;
        BODY_1: string;
        BODY_2: string;
    }
    ROOM_SELECT: {
        TITLE: string;
        ROTATE_TEXT: string;
        OPEN: string;
    }
    NOTIFICATION: {
        NEW_MESSAGE: string;
    }
    CLOSED: {
        TITLE: string;
        BODY_1: string;
    }
}
// #endregion